    modifiers = ' '.join(self.type_modifiers)
    syntax = ''
    if self.reference:
        syntax += '&'
    if self.pointer:
        syntax += '*'
    templated_types = ''
    if self.templated_types:
        templated_types = '<%s>' % ', '.join(self.templated_types)
    suffix = '%s %s%s %s' % (modifiers, self.type_name, templated_types + syntax, self.name)
